        /// <summary>The country's months, oldest first.</summary>
        public static (int Year, int Month, float Unemployment, float Inflation)[] For(PoliSim.Data.CountryId id)
        {
            switch (id)
            {
                case PoliSim.Data.CountryId.USA: return USA;
                case PoliSim.Data.CountryId.Sweden: return Sweden;
                case PoliSim.Data.CountryId.Germany: return Germany;
                case PoliSim.Data.CountryId.France: return France;
                case PoliSim.Data.CountryId.Italy: return Italy;
                case PoliSim.Data.CountryId.Poland: return Poland;
                default: return new (int, int, float, float)[0];
            }
        }
    }
